#include "mem_init.h"

#include <algorithm>
#include <array>
#include <map>
#include <memory>
#include <set>
#include <vector>

#include "image_bits.hpp"
#include "scamptrie_dynamic.h"

namespace {

struct BNode;

struct BEdge {
    uint32_t key = 0;
    BNode* kid = nullptr;
    bool bulk = false;
};

struct BNode {
    uint32_t origin = 0;        // forest origin: 0, 16 or 64
    uint32_t max_len = 128;     // owner group maximum length
    uint32_t depth = 0;         // global depth of this node
    uint64_t rhi = 0, rlo = 0;  // region bits, normalized to depth
    int type = 1;
    std::vector<FibPfx> own;    // local prefixes (TYPE1/2/3) or inline (TYPE4/5)
    std::vector<BEdge> edges;   // children in increasing key order
    uint32_t height = 0;        // longest downward path in edges
    uint32_t stage = 0;
    uint32_t cell = 0;
    uint32_t csize = 1;         // charged cells inside its stage
    bool in_block = false;      // child of a TYPE3 bulk array
    uint32_t bulk_stage = 0;
    uint64_t bulk_bitmap = 0;
    uint32_t n_direct = 0;
    uint64_t pattern = 0;
    std::vector<std::pair<uint32_t, uint32_t> > ni;  // (position, hop) by position
    uint32_t bitmap_id = 0;
    uint32_t ni_base = 0;
    uint32_t bmp = BMP_NULL_VALUE;
};

struct Builder {
    std::vector<std::unique_ptr<BNode> > arena;
    std::vector<BNode*> nodes;  // creation order
    std::array<uint32_t, RAM_NUM> cells{};

    BNode* alloc() {
        std::unique_ptr<BNode> n(new BNode());
        BNode* raw = n.get();
        arena.push_back(std::move(n));
        nodes.push_back(raw);
        return raw;
    }

    // Recursive compact subtree. Every prefix of 'set' matches the region and
    // has length in [depth, max_len].
    BNode* build(uint32_t origin, uint32_t max_len, uint32_t depth,
                 uint64_t rhi, uint64_t rlo, const std::vector<FibPfx>& set) {
        BNode* n = alloc();
        n->origin = origin;
        n->max_len = max_len;
        n->depth = depth;
        n->rhi = rhi;
        n->rlo = rlo;
        if (set.size() <= 2) {
            // One or two owned prefixes collapse into a single half/full node.
            n->type = (set.size() == 1) ? 4 : 5;
            n->own = set;
            return n;
        }
        std::vector<FibPfx> local;
        std::map<uint32_t, std::vector<FibPfx> > kids;
        for (size_t i = 0; i < set.size(); ++i) {
            const FibPfx& p = set[i];
            if (p.len <= depth + 5) {
                local.push_back(p);
            } else {
                uint32_t key = static_cast<uint32_t>(fib_bits(p.hi, p.lo, depth, 6));
                kids[key].push_back(p);
            }
        }
        n->own = local;
        for (std::map<uint32_t, std::vector<FibPfx> >::iterator it = kids.begin(); it != kids.end(); ++it) {
            uint64_t chi = rhi, clo = rlo;
            fib_set_bits(chi, clo, depth, 6, it->first);
            BEdge e;
            e.key = it->first;
            e.kid = build(origin, max_len, depth + 6, chi, clo, it->second);
            n->edges.push_back(e);
        }
        size_t k = n->edges.size();
        n->type = (k <= 2) ? 1 : (k <= 6) ? 2 : 3;
        return n;
    }

    void calc(BNode* n) {
        for (size_t i = 0; i < n->edges.size(); ++i) calc(n->edges[i].kid);
        if (n->type == 3) {
            size_t k = n->edges.size();
            // At most three direct children; the (at least four) others bulk.
            n->n_direct = static_cast<uint32_t>(std::min<size_t>(3, k - 4));
            uint32_t bs = 0;
            for (size_t i = n->n_direct; i < k; ++i) {
                n->edges[i].bulk = true;
                bs = std::max(bs, n->edges[i].kid->height);
            }
            n->bulk_stage = bs;
        }
        for (size_t i = 0; i < n->edges.size(); ++i) {
            uint32_t st = n->edges[i].bulk ? n->bulk_stage : n->edges[i].kid->height;
            n->height = std::max(n->height, st + 1);
        }
    }

    void assign_stage(BNode* n, uint32_t stage) {
        n->stage = stage;
        for (size_t i = 0; i < n->edges.size(); ++i) {
            BEdge& e = n->edges[i];
            assign_stage(e.kid, e.bulk ? n->bulk_stage : e.kid->height);
        }
    }

    // Dense, non overlapping slot layout per stage. Two cell slots always start
    // at an even cell; half nodes fill rows in pairs, so at most the very last
    // cell of a stage is odd and its row half stays zero padding.
    void place() {
        std::vector<std::vector<BNode*> > blocks[RAM_NUM];
        std::vector<BNode*> fulls[RAM_NUM], halfs[RAM_NUM];
        for (size_t i = 0; i < nodes.size(); ++i) {
            BNode* n = nodes[i];
            n->csize = static_cast<uint32_t>(image_cell_size(n->type));
            if (n->type != 3) continue;
            std::vector<BNode*> blk;
            for (size_t j = 0; j < n->edges.size(); ++j) {
                if (!n->edges[j].bulk) continue;
                blk.push_back(n->edges[j].kid);
                n->edges[j].kid->in_block = true;
            }
            if (!blk.empty()) blocks[n->bulk_stage].push_back(blk);
        }
        for (size_t i = 0; i < nodes.size(); ++i) {
            BNode* n = nodes[i];
            if (n->in_block) continue;
            if (n->csize == 1) halfs[n->stage].push_back(n);
            else fulls[n->stage].push_back(n);
        }
        for (uint32_t s = 0; s < RAM_NUM; ++s) {
            uint32_t cell = 0;
            for (size_t b = 0; b < blocks[s].size(); ++b) {
                std::vector<BNode*>& blk = blocks[s][b];
                for (size_t x = 0; x < blk.size(); ++x) {
                    blk[x]->cell = cell;
                    blk[x]->csize = 2;  // bulk roots always charge two cells
                    cell += 2;
                }
            }
            for (size_t x = 0; x < fulls[s].size(); ++x) { fulls[s][x]->cell = cell; cell += 2; }
            for (size_t x = 0; x < halfs[s].size(); ++x) { halfs[s][x]->cell = cell; cell += 1; }
            cells[s] = cell;
        }
    }

    void collect_ni(BNode* n) {
        if (n->type == 4 || n->type == 5) return;
        n->pattern = 0;
        n->ni.clear();
        for (size_t i = 0; i < n->own.size(); ++i) {
            const FibPfx& p = n->own[i];
            uint32_t l = p.len - n->depth;
            uint32_t v = static_cast<uint32_t>(fib_bits(p.hi, p.lo, n->depth, l));
            uint32_t pos = (1u << l) + v;
            n->pattern |= (1ULL << pos);
            n->ni.push_back(std::make_pair(pos, p.hop));
        }
        std::sort(n->ni.begin(), n->ni.end());
    }
};

uint64_t inline_fragment(uint32_t origin, const FibPfx& p) {
    if (origin == 0) return p.hi;
    if (origin == 16) return p.hi << 16;
    return p.lo;
}

}  // namespace

ImageData build_image(const Fib& fib) {
    ImageData img;
    std::vector<FibPfx> all = fib.all();

    std::vector<FibPfx> g0;
    std::map<uint16_t, std::vector<FibPfx> > g16;
    std::map<uint64_t, std::vector<FibPfx> > g64;
    for (size_t i = 0; i < all.size(); ++i) {
        const FibPfx& p = all[i];
        if (p.len <= 16) g0.push_back(p);
        else if (p.len <= 64) g16[static_cast<uint16_t>(p.hi >> 48)].push_back(p);
        else g64[p.hi].push_back(p);
    }

    Builder builder;
    std::vector<BNode*> roots0;
    if (!g0.empty()) roots0.push_back(builder.build(0, 16, 0, 0, 0, g0));
    std::vector<std::pair<uint16_t, BNode*> > roots16;
    for (std::map<uint16_t, std::vector<FibPfx> >::iterator it = g16.begin(); it != g16.end(); ++it)
        roots16.push_back(std::make_pair(
            it->first, builder.build(16, 64, 16, static_cast<uint64_t>(it->first) << 48, 0, it->second)));
    std::vector<std::pair<uint64_t, BNode*> > roots64;
    for (std::map<uint64_t, std::vector<FibPfx> >::iterator it = g64.begin(); it != g64.end(); ++it)
        roots64.push_back(std::make_pair(
            it->first, builder.build(64, 128, 64, it->first, 0, it->second)));

    for (size_t i = 0; i < roots0.size(); ++i) builder.calc(roots0[i]);
    for (size_t i = 0; i < roots16.size(); ++i) builder.calc(roots16[i].second);
    for (size_t i = 0; i < roots64.size(); ++i) builder.calc(roots64[i].second);
    for (size_t i = 0; i < roots0.size(); ++i) builder.assign_stage(roots0[i], roots0[i]->height);
    for (size_t i = 0; i < roots16.size(); ++i) builder.assign_stage(roots16[i].second, roots16[i].second->height);
    for (size_t i = 0; i < roots64.size(); ++i) builder.assign_stage(roots64[i].second, roots64[i].second->height);
    builder.place();

    std::set<uint64_t> pattern_set;
    for (size_t i = 0; i < builder.nodes.size(); ++i) {
        BNode* n = builder.nodes[i];
        builder.collect_ni(n);
        if (n->type != 4 && n->type != 5) pattern_set.insert(n->pattern);
    }
    img.bitmaps.assign(pattern_set.begin(), pattern_set.end());
    std::map<uint64_t, uint32_t> pattern_id;
    for (size_t i = 0; i < img.bitmaps.size(); ++i) pattern_id[img.bitmaps[i]] = static_cast<uint32_t>(i);

    for (size_t i = 0; i < builder.nodes.size(); ++i) {
        BNode* n = builder.nodes[i];
        n->bmp = fib.lookup_upto(n->rhi, n->rlo, n->depth);
        if (n->bmp == FIB_NO_HOP) n->bmp = BMP_NULL_VALUE;
        if (n->type == 4 || n->type == 5) continue;
        n->bitmap_id = pattern_id[n->pattern];
        n->ni_base = static_cast<uint32_t>(img.nexthops.size());
        for (size_t j = 0; j < n->ni.size(); ++j) img.nexthops.push_back(n->ni[j].second);
    }

    for (uint32_t s = 0; s < RAM_NUM; ++s) {
        img.cells[s] = builder.cells[s];
        img.banks[s].assign((img.cells[s] + 1) / 2, std::bitset<256>());
    }

    for (size_t i = 0; i < builder.nodes.size(); ++i) {
        BNode* n = builder.nodes[i];
        if (n->stage >= RAM_NUM || n->cell + n->csize > img.cells[n->stage]) continue;
        bool half = image_is_half(n->type) != 0;
        std::bitset<256>& word = img.banks[n->stage][n->cell / 2];
        int p = half ? static_cast<int>((n->cell % 2) * 128) : 0;
        int start = p;
        std::vector<uint32_t> keys;
        std::vector<BNode*> kids;
        for (size_t j = 0; j < n->edges.size(); ++j)
            if (!n->edges[j].bulk) { keys.push_back(n->edges[j].key); kids.push_back(n->edges[j].kid); }
        if (n->type == 4 || n->type == 5) {
            rec_put(word, p, OFF_TYPE_W, static_cast<uint64_t>(n->type)); p = start + OFF_BMP;
            rec_put(word, p, OFF_BMP_W, n->bmp); p = start + OFF_INLINE;
            for (size_t j = 0; j < n->own.size(); ++j) {
                const FibPfx& pf = n->own[j];
                rec_put(word, p, OFF_FRAG_W, inline_fragment(n->origin, pf)); p += OFF_FRAG_W;
                rec_put(word, p, OFF_LEN_W, pf.len - n->origin); p += OFF_LEN_W;
                rec_put(word, p, OFF_HOP_W, pf.hop); p += OFF_HOP_W;
            }
        } else {
            rec_put(word, p, OFF_TYPE_W, static_cast<uint64_t>(n->type)); p = start + OFF_BMP;
            rec_put(word, p, OFF_BMP_W, n->bmp); p = start + OFF_BITMAP_ID;
            rec_put(word, p, OFF_BITMAP_ID_W, n->bitmap_id); p += OFF_BITMAP_ID_W;
            rec_put(word, p, OFF_NI_BASE_W, n->ni_base); p += OFF_NI_BASE_W;
            if (n->type == 3) {
                uint64_t bulk = 0;
                uint32_t base = 0;
                bool first = true;
                for (size_t j = 0; j < n->edges.size(); ++j) {
                    if (!n->edges[j].bulk) continue;
                    bulk |= (1ULL << n->edges[j].key);
                    if (first) { base = n->edges[j].kid->cell; first = false; }
                }
                n->bulk_bitmap = bulk;
                rec_put(word, p, OFF_BULK_BMP_W, bulk); p += OFF_BULK_BMP_W;
                rec_put(word, p, OFF_BULK_BASE_W, base); p += OFF_BULK_BASE_W;
                rec_put(word, p, OFF_BULK_STAGE_W, n->bulk_stage); p += OFF_BULK_STAGE_W;
                for (size_t j = 0; j < 3; ++j) {
                    uint32_t child = IMAGE_ABSENT_CHILD;
                    if (j < kids.size()) {
                        child = keys[j] | ((kids[j]->stage & 0xFu) << 6) | ((kids[j]->cell & IMAGE_CELLS_MAX) << 10);
                    }
                    rec_put(word, p, OFF_CHILD_W, child); p += OFF_CHILD_W;
                }
            } else {
                size_t want = (n->type == 1) ? 2 : 6;
                for (size_t j = 0; j < want; ++j) {
                    uint32_t child = IMAGE_ABSENT_CHILD;
                    if (j < kids.size()) {
                        child = keys[j] | ((kids[j]->stage & 0xFu) << 6) | ((kids[j]->cell & IMAGE_CELLS_MAX) << 10);
                    }
                    rec_put(word, p, OFF_CHILD_W, child); p += OFF_CHILD_W;
                }
            }
        }
    }

    if (!roots0.empty()) {
        img.root.stage = static_cast<int>(roots0[0]->stage);
        img.root.cell = roots0[0]->cell;
    } else {
        img.root.stage = -1;
        img.root.cell = 0;
    }
    for (size_t i = 0; i < roots16.size(); ++i) {
        ImageFront f;
        f.key = roots16[i].first;
        f.loc.stage = static_cast<int>(roots16[i].second->stage);
        f.loc.cell = roots16[i].second->cell;
        img.front16.push_back(f);
    }
    for (size_t i = 0; i < roots64.size(); ++i) {
        ImageFront f;
        f.key = roots64[i].first;
        f.loc.stage = static_cast<int>(roots64[i].second->stage);
        f.loc.cell = roots64[i].second->cell;
        img.front64.push_back(f);
    }
    return img;
}

MemInit::MemInit(ScampTrieDynamic* trie) : trie_(trie) {}

MemInit::~MemInit() {}

ImageData MemInit::capture() { return build_image(trie_->fib()); }
